const content=document.getElementById("handbookContent"),searchInput=document.getElementById("searchInput"),sectionCount=document.getElementById("sectionCount"),searchStatus=document.getElementById("searchStatus"),noResults=document.getElementById("noResults"),tabs=document.getElementById("sopTabs");
function inline(t){return t.replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/\*\*(.+?)\*\*/g,"<strong>$1</strong>").replace(/`(.+?)`/g,"<code>$1</code>")}
function slug(t){return t.toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"")}
function renderMarkdown(md){const lines=md.replace(/\r/g,"").split("\n");let html="",inList=false,listType="",inTable=false,n=0;const cl=()=>{if(inList){html+="</"+listType+">";inList=false;listType=""}},ct=()=>{if(inTable){html+="</tbody></table>";inTable=false}},cb=()=>{cl();ct()};for(const line of lines){if(!line.trim()){cb();continue}if(/^# /.test(line)){cb();const title=line.replace(/^# /,"").trim();if(n++)html+="</div></article>";const id=slug(title)||"section-"+n;html+='<article class="sop-section" id="'+id+'" data-section="'+inline(title)+'"><h2>'+inline(title)+'</h2><div class="section-body">';continue}if(/^## /.test(line)||/^### /.test(line)){cb();html+="<h3>"+inline(line.replace(/^#{2,3} /,""))+"</h3>";continue}if(/^\|/.test(line)){cl();const cells=line.trim().replace(/^\|/,"").replace(/\|$/,"").split("|").map(c=>c.trim());if(/^[\s:|-]+$/.test(line.replace(/[|]/g,"")))continue;if(!inTable){inTable=true;html+="<table><thead><tr>"+cells.map(c=>"<th>"+inline(c)+"</th>").join("")+"</tr></thead><tbody>"}else html+="<tr>"+cells.map(c=>"<td>"+inline(c)+"</td>").join("")+"</tr>";continue}else ct();const ul=/^\s*[-*]\s+/.test(line),ol=/^\s*\d+\.\s+/.test(line);if(ul||ol){const w=ul?"ul":"ol";if(!inList||listType!==w){cl();inList=true;listType=w;html+="<"+w+">"}html+="<li>"+inline(line.replace(/^\s*(?:[-*]|\d+\.)\s+/,""))+"</li>";continue}cl();if(/^---+$/.test(line.trim())){html+="<hr>";continue}if(/^>/.test(line)){html+="<blockquote>"+inline(line.replace(/^>\s?/,""))+"</blockquote>";continue}html+="<p>"+inline(line.trim())+"</p>"}cb();if(n)html+="</div></article>";return html}
const groups=[{id:"department",label:"Department SOPs",test:t=>!/^(26\. H\.E\.A\.T\.|27\. Air Support|28\. K-9|29\. Detective|30\. Motorcycle|31\. General Division|32\. Internal Affairs)/i.test(t)},{id:"heat",label:"H.E.A.T.",test:t=>/^26\. H\.E.A\.T\./i.test(t)},{id:"air",label:"Air Support",test:t=>/^27\. Air Support/i.test(t)},{id:"k9",label:"K-9",test:t=>/^28\. K-9/i.test(t)},{id:"detectives",label:"Detectives",test:t=>/^29\. Detective/i.test(t)},{id:"mcu",label:"M.C.U.",test:t=>/^30\. Motorcycle/i.test(t)},{id:"general",label:"General Division Policy",test:t=>/^31\. General Division/i.test(t)},{id:"ia",label:"Internal Affairs",test:t=>/^32\. Internal Affairs/i.test(t)}];let active="department",panels=new Map();
Promise.resolve("# Backstreets Police Department – Complete SOP Changes & Updated Rules\n\nThis combines both documents:\n\n1. The original LSPD SOP change announcements.\n2. The current Backstreets Police Department SOP document.\n\nI've consolidated the information into one master reference, including the additional rules in the full SOP, later updates, and conflicting rules that need clarification.\n\nThe goal is to have everything in one place so officers can review the current policies without searching through multiple Discord announcements.\n\n# 1. General Department Policies\n\n## Chain of Command\n\n- Officers must respect the chain of command.\n- Follow instructions and corrections from higher-ranking personnel.\n- Operational questions should go to your supervisor first.\n- If your supervisor is unavailable, escalate through the chain of command.\n- Failure to follow the chain of command may result in disciplinary action.\n\n## Activity Requirements\n\n- Minimum activity: 5 hours per week.\n- Inactivity exceeding one week without an approved LOA results in one strike point per week.\n- LOAs must be submitted through PD Emails.\n- LOAs can last up to one month before renewal is required.\n\n## Off-Duty Regulations\n\n- Officers must be fully clocked out.\n- Police equipment must be stored in personal lockers.\n- Police uniforms and department vehicles cannot be used off duty.\n- Officers cannot intervene in crimes while off duty.\n- Officers must call law enforcement and comply with responding officers.\n- Unprofessional or aggressive off-duty behavior can result in disciplinary action.\n\n## Badges\n\n- Officers must carry their badges while on duty.\n- When requested, officers must provide their name, callsign and proof of identity.\n- Failure to identify yourself may result in disciplinary action, demotion or termination.\n\n# 2. Rank Structure and Permissions\n\n| Rank                 | Callsign    | Permissions                                              |\n| -------------------- | ----------- | -------------------------------------------------------- |\n| Commissioner         | W-XXX (001) | Oversees the department                                  |\n| High Command         | L-001–L-014 | 14 positions; department oversight and legal matters     |\n| Command              | L-101–L-299 | Lieutenants/Captains; fully unmarked vehicles            |\n| Supervisor           | L-301–L-599 | Corporals/Sergeants; slicktop vehicles                   |\n| Senior Officer       | L-601–L-699 | Eligible for FTO and Class 2                             |\n| Officer              | L-701–L-799 | General patrol and emergency imports                     |\n| Probationary Officer | L-801–L-899 | Can patrol solo and respond to non-gang-turf shots fired |\n| Cadet                | L-901–L-999 | Must ride with an FTO when available                     |\n\nAdditional requirements:\n\n- Senior Officers need at least one week of experience before promotion to Supervisor.\n- Cadets must complete firearm training to receive Class 1 certification.\n- Cadets cannot patrol solo unless they are the only officers available or High Command approves it.\n\n# 3. Equipment, Weapons and Bodycams\n\n## Required Equipment\n\n- Bodycam.\n- Taser.\n- Handcuffs.\n- Radio.\n- IFaks.\n- Armour.\n- Police shield.\n- Spike strips.\n- Flashlight.\n- Evidence camera.\n- Mobile fingerprint scanner.\n- Evidence pouch.\n- DNA swab kits.\n- Access tool.\n- Diving suit.\n\n## Weapon Requirements\n\n| Weapon             | Minimum Rank    | Certification |\n| ------------------ | --------------- | ------------- |\n| White/Pink Taser   | Cadet+          | —             |\n| PD 57              | Cadet+          | —             |\n| Switches           | Officer+        | —             |\n| PD SMG             | Senior Officer+ | Class 2       |\n| PD Glock           | Cadet+          | Class 1       |\n| PD M4              | Sergeant+       | Class 3       |\n| Non-Lethal Shotgun | Lieutenant+     | Class 4       |\n| MP7F               | QRT/SWAT        | Class 2       |\n| SWAT LBRS          | QRT/SWAT        | Class 3       |\n| Lethal Shotgun     | QRT/SWAT        | Class 4       |\n| PD Sniper          | QRT/SWAT        | Class 4       |\n\nAmmunition limits:\n\n- PD 57: 150 pistol bullets.\n- PD SMG: 200 SMG bullets.\n- PD Glock: 100 pistol bullets.\n- PD M4: 150 AR bullets.\n\nAdditional announcement:\n\n- High Command may use every weapon except the sniper.\n- PD Glock use is restricted to Code Red vehicles.\n\n## Bodycam – Section 2.2\n\n- Officers must have active in-city and in-head bodycams.\n- OBS is recommended for recording full sessions.\n- Officers should record every scene from beginning to end.\n- Footage must establish probable cause and supporting evidence.\n- Bodycam footage cannot be deleted within 24 hours of recording.\n- Bodycams are no longer instantly uploaded.\n- Officers must return to HQ to collect their unbroken bodycam from a scene.\n- If a suspect uses `/me breaks bodycam`, the footage from that particular scene has no meaning in an investigation.\n- Officers must act as though they do not know what happened if the footage is invalidated under this rule.\n\n## Uniform Regulations\n\n- Correct department uniforms must be worn.\n- Accessories are allowed, but gang accessories and excessively large chains are prohibited.\n- Masks are restricted to certain divisions, such as SWAT.\n- Face tattoos and face paint are prohibited.\n\n## Vehicle Regulations\n\n- Cadets may use bicycles when not riding with an FTO.\n- Emergency lights are required until Command rank.\n- Liveries may be removed at Corporal.\n- One interceptor per four four-door patrol units.\n- One interceptor per pursuit.\n- Officers must check with dispatch before taking another interceptor.\n\nVehicle color permissions:\n\n- Supervisor+: Grey with livery and slicktop.\n- Command+: Black or white, marked or unmarked.\n- Senior Detective: Black slicktop with livery.\n- Detective First Grade: Black slicktop or unmarked.\n- Other colors require High Command approval.\n\n# 4. Search, Seizure and Probable Cause\n\n## Reasonable Suspicion\n\n- Reasonable suspicion is a suspicion without concrete evidence.\n- Officers may temporarily detain a suspect for investigation and public safety.\n- Searching is not permitted under reasonable suspicion alone.\n- The detention must be explained as an investigation, not an arrest.\n- Maximum detention: 24 in-head minutes.\n\n## Probable Cause\n\n- Evidence connecting a suspect to a crime.\n- Examples include matching shell casings, witnessing a crime or discovering relevant contraband during an investigation.\n- Probable cause permits an arrest.\n\n## Section 4.2.2 – Search and Seizure\n\n- Searches require probable cause or explicit consent.\n- Officers may search or frisk suspects in the field when proper probable cause or consent exists.\n- Contraband may be seized in the field or at HQ.\n\n## Shots Fired Investigations\n\n- GSR testing does not require consent for 10-13 calls.\n- Negative GSR results mean the suspect should not be searched and is free to leave.\n- Positive results require Miranda Rights and detention.\n- Officers may look for bullet casings.\n- A discovered casing permits a frisk for a weapon.\n- Weapon serial numbers should be crossmatched against recovered casings.\n- Officers must consider whether the weapon was used in self-defense.\n\n## Drug Sale Investigations\n\n- Non-K9 officers need bodycam footage of a confirmed handoff before engaging.\n- Officers should communicate with the suspect and investigate before proceeding.\n- Exceptions exist for immediate threats or ongoing criminal activity.\n- After a confirmed handoff, the suspect may be arrested.\n- Officers should not immediately draw weapons.\n- After cuffing, suspects should receive medical attention if needed before searches.\n- Connected vehicles may also be searched.\n- Illegal drugs and items may be confiscated.\n- K9 deployment requires clear and reasonable suspicion.\n- K9s cannot be used on every routine traffic stop without justification.\n\n# 5. Scene Conduct and Miranda Rights\n\n## Scene Completion\n\n- When the majority of PD is wiped and EMS has arrived, the scene is over.\n- All evidence from that scene becomes invalid.\n\n## Miranda Rights – Section 4.4\n\n- Officers must read Miranda Rights to suspects in custody when detained or arrested and being questioned.\n- Failure to read rights does not invalidate an arrest.\n- Statements made before rights are read are inadmissible evidence.\n\n## Evidence and Reporting\n\n- Officers must log all appropriate reports.\n- Gun confiscations, mugshots and evidence must be recorded.\n- Proper documentation is required through the department's designated channels.\n\n# 6. Use of Force – Section 5\n\n## General Use-of-Force Levels\n\n| Level   | Type                    |\n| ------- | ----------------------- |\n| Level 1 | Officer presence        |\n| Level 2 | Verbal communication    |\n| Level 3 | Hand-to-hand / tackling |\n| Level 4 | Non-lethal force        |\n| Level 5 | Deadly force            |\n\nGeneral principles:\n\n- Preserve human life whenever possible.\n- Use objectively reasonable force.\n- Match force to the danger presented.\n- Lethal force requires an imminent threat, intent and a weapon or other identified threat.\n- Officers must communicate before escalating whenever possible.\n\n## Matching Force – Section 5.1\n\n- Officers must match their force to the situation.\n- A weapon being brandished requires at least one verbal command to drop it.\n- A weapon pointed at officers or civilians creates an immediate public safety concern.\n- If an officer goes down or activates a panic button, responding officers may use matching force.\n\n## Taser – Section 5.2\n\n- Officers must give verbal warnings before deployment.\n- Officers must announce when they are going for a taser.\n- A 15-second interval is required between taser shots.\n- Do not repeatedly tase a suspect.\n- Do not tase suspects on ladders, rooftop edges or near dangerous drops.\n- Avoid tasing people standing in water.\n- Anyone tased in water must immediately be removed from the drowning risk.\n- A suspect attempting to enter a vehicle may be tased before entering.\n- A suspect already inside a vehicle may be tased after announcing deployment.\n\n## Tackling – Section 5.3\n\n- Officers must verbalize the tackle warning.\n- Officers must announce that they are going for a tackle.\n- Do not repeatedly tackle someone without giving them a reasonable opportunity to comply.\n- Allow a tackled suspect to stand and surrender.\n- A second tackle may be used if the suspect gets up and remains non-compliant.\n\n## Cuffing – Section 5.4\n\n- Instruct suspects to put their hands up and face away.\n- Officers must announce when they are going for cuffs.\n- Non-compliance may require escalation.\n- Suspects who are tackled or tased may be cuffed while on the ground.\n- Do not spam cuffs if the first cuff breaks.\n- Cuffing someone while running or walking is considered power cuffing.\n- Power cuffing can result in a strike and possible government punishment.\n- Hard cuffs are a last resort and should only be used when a suspect is not properly roleplaying.\n- Regular hard-cuff abuse results in disciplinary action.\n\n## Non-Lethal Shotgun – Section 5.5\n\n- Cannot be used as a primary taser.\n- 10-second cooldown between shots.\n- Command+ authorization required.\n- Class 3 certification required.\n- Verbal commands must be given before use.\n- Abuse can result in privilege revocation and disciplinary action.\n\nApproved situations:\n\n- Bank heists.\n- House/store robberies.\n- MLO breaches and gang blocks.\n- Executing signed warrants.\n- Crowd control.\n- Prison transports.\n- Hostage rescues.\n- Certain vehicle extractions involving non-compliant occupants.\n\n## Police Shields – Section 5.6\n\n- Only the black shield labeled Police Shield is permitted.\n- Maximum of 3 shields per scene.\n- Class 1 weapons only while equipped.\n\nApproved situations:\n\n- Bank heists.\n- House/store robberies.\n- MLO breaches and gang blocks.\n- Executing signed warrants.\n- Crowd control.\n- Prison transports.\n- Hostage rescues.\n\n## Air-1 – Section 5.7\n\n- A co-pilot is mandatory.\n- Passengers may respond with matching force if the aircraft is shot at.\n- Class 1 weapons are restricted to specified vehicle-disabling or water-dumping situations during an active 10-80.\n- Refer to the Air-1 SOP for additional requirements.\n\n# 7. Certifications and Divisions\n\n## Division Requirements – Section 6.1\n\n- Officers with 3 or more active strikes cannot join divisions.\n- Existing division members are removed when they reach 3 active strikes.\n- They may reapply once their active strikes fall below 3.\n- Certifications are privileges, not guaranteed entitlements.\n- Violations can result in certification revocation.\n\n## Certification Requirements\n\n| Certification             | Rank           | Requirements                         |\n| ------------------------- | -------------- | ------------------------------------ |\n| Class 1                   | Cadet          | FTO training and shooting assessment |\n| Class 2                   | Senior Officer | FTO training and shooting assessment |\n| Class 3                   | Sergeant       | FTO training and shooting assessment |\n| Additional certifications | Eligible ranks | Application and SOP quiz             |\n\nOfficers must demonstrate knowledge of:\n\n- Use of Force.\n- Matching Force.\n- Their respective certification SOPs.\n\n## Divisions\n\n| Division      | Minimum rank / requirements |\n| ------------- | --------------------------- |\n| FTO/FTA       | Senior Officer              |\n| FTO Oversight | Sergeant                    |\n| K9            | Senior Officer              |\n| QRT           | Senior Officer              |\n| Detectives    | Senior Officer              |\n\n- FTO/FTA applicants must demonstrate their training abilities.\n- FTO Oversight trains officers to become FTOs.\n- FTO Oversight requires a High Command-reviewed application.\n- K9, QRT and Detectives require applications and division-specific training.\n\n## K9 Unit – Section 6.2\n\n- K9 units are treated as officers.\n- Harming a K9 may result in the same punishment as harming an officer.\n- K9s must be deployed from the station and placed in the officer's vehicle before patrol.\n- K9s cannot be deployed midway through a scene.\n- Officers with a deployed K9 cannot conduct civilian or officer ride-alongs.\n- Only one K9 may be active per scene.\n- Special deployment rules apply during shootouts and foot pursuits.\n- At least two warnings are required before a K9 is sent to attack during a foot pursuit.\n\n# 8. Arrests and Processing – Section 7\n\n## General Processing\n\n- The primary officer should transport arrested suspects.\n- A secondary officer may assist when multiple suspects need transportation.\n- Other officers must return to patrol after the scene is Code 4 unless handling evidence.\n- Officers must not remain at the station unnecessarily.\n- Additional units may escort processing officers if there is a suspected breakout attempt.\n\n## Maximum Penalties\n\nMaximum fine\n\n# $200,000\n\nMaximum sentence\n\n# 200 months\n\n## Processing Procedure\n\n- Read Miranda Rights once the suspect is cuffed.\n- Ask whether the suspect wants an available lawyer.\n- If requested, the suspect contacts DOJ services once uncuffed in the cells.\n- Requesting a lawyer does not automatically reduce jail time.\n- Ask whether the suspect requires medical attention.\n- Contact EMS when necessary.\n- If the suspect is fully down, CPR is required until EMS arrives.\n- Conduct a final search in the station garage.\n- Obtain a clear mugshot and fingerprint.\n- Masks or obstructing accessories may be removed for identification.\n- Failure to provide fingerprints results in maximum fine and sentence.\n- Complete the MDT report and charges.\n\n## Holding Cells\n\n- Maximum holding time: 24 in-head minutes.\n- Exception: A suspect requesting a lawyer may be held until their lawyer arrives.\n\n## Insufficient Funds\n\n- Officers may add one month per $1,000 owed when the suspect cannot afford their fine.\n- This cannot exceed the 200-month maximum.\n\n## Guilty Pleas\n\n- Officers may reduce the sentence by 50% when a suspect pleads guilty.\n- The reduction is at the arresting officer's discretion.\n\n# 9. Gun Confiscation and Buybacks\n\n## Section 7.2 – Confiscation\n\nEvery confiscated firearm requires:\n\n- An MDT report, even if no arrest is made.\n- A Dyno log in `#weapon-confiscation`.\n- A weapon strike check when applicable.\n- Placement in the appropriate Criminal CID evidence stash.\n- If a suspect escapes or pops their head, the firearm must be placed in the CID Evidence stash.\n\n## Confiscation Rules\n\n| Circumstance                 | Required action                       |\n| ---------------------------- | ------------------------------------- |\n| Gun not used + valid license | Return before jailing                 |\n| Gun not used + no license    | $50,000 charge; return before jailing |\n| Gun used in violent crime    | Confiscate and apply weapon strike    |\n\nWeapon strikes are tied to individual serial numbers.\n\n| Strike | Consequence            |\n| ------ | ---------------------- |\n| 1      | First offense          |\n| 2      | Second offense         |\n| 3      | Permanent confiscation |\n\nOfficers must record the strike number in the MDT report.\n\n## Section 8.2 – Weapon Buybacks\n\n- Only F9-registered weapons qualify.\n- Non-F9 weapons cannot be bought back.\n- Weapons with 3 or more violent strikes are ineligible.\n- A weapon license is not required.\n- All buybacks must be recorded using Dyno in `#gun-buyback`.\n- Failure to log buybacks may be treated as PD corruption.\n\n| Weapon class | Buyback price |\n| ------------ | ------------- |\n| Class 1      | $100,000      |\n| Class 2      | $200,000      |\n| Class 3      | $300,000      |\n\n## Weapon Licenses – Section 8.1\n\n- Licenses are only issued to individuals with clean records.\n- Previous convictions must be expunged before obtaining a license.\n- Licenses may be revoked when weapons are used in violent felonies.\n- Self-defense is an exception if the individual provides bodycam evidence supporting their claim.\n\n# 10. Warrants, Search Warrants, Bail and Expungements\n\n## Section 9.1 – Warrants\n\nOfficial warrants\n\n- Issued by Detectives/FIB through the MDT.\n- Valid for one week.\n- Dropped if the suspect cannot be found after one week.\n- Officers may attempt service at a player's location once every two hours.\n- If the suspect is not present, officers must leave.\n\nUnofficial in-city warrants\n\n- Corporal+ may issue them over the radio.\n- Require proper bodycam and evidence.\n- Last 3 hours in head.\n- Cannot be entered into the MDT.\n- Must be communicated verbally through radio.\n- The current SOP limits these warrants to criminal charges and excludes attempted murder of a government official.\n\nAdditional restrictions\n\n- Officers cannot lure or entrap suspects to serve warrants.\n- Warrants must be served naturally.\n- Warrants cannot be served inside Green Zones.\n\n## Section 9.2 – Search Warrants\n\n- Detectives may request search warrants through DOJ Discord.\n- Proper evidence is required.\n- Search warrants may be used to collect crime evidence or make an arrest inside a property.\n- A signed warrant is required before breaching a player's house.\n- Unauthorized breaches can result in SOP failure or PD corruption.\n\n## Section 9.3 – Bail\n\n- Bail is generally available for non-violent crimes.\n- Officers have discretion over whether to accept bail.\n- Violent-crime bail requires High Command approval.\n- Suspects must plead guilty.\n- A suspect who accepts bail cannot later challenge the charges through DOJ.\n- Suspects must be informed of this before accepting.\n- Bail costs $1,000 per month of the original sentence.\n- Bail is added on top of the original fine.\n\nExample:\n\n| Item              | Amount       |\n| ----------------- | ------------ |\n| Original fine     | $50,000      |\n| 50-month sentence | $50,000 bail |\n| Total             | $100,000     |\n\n## Section 9.4 – Expungements\n\n- At least 24 hours must pass before expungement.\n- Each charge costs $10,000.\n- Officers must remove the charge from the incident.\n- Save the incident.\n- Add a note to the individual's profile.\n\nThe change announcements initially transferred expungements to DOJ, but a later update returned responsibility to PD until DOJ is fully operational.\n\n# 11. Vehicle Impounding – Section 10\n\nOfficers must use `/impound` and complete:\n\n- Impounded by.\n- Reason.\n- Release fee.\n- Mark retrievable by owner.\n\n## Impound Fees\n\n| Offense                   | Fee     | Hold time |\n| ------------------------- | ------- | --------- |\n| Illegally parked          | $500    | Instant   |\n| Reckless driving          | $1,000  | Instant   |\n| Hit and run               | $1,500  | Instant   |\n| Stolen vehicle            | $2,000  | Instant   |\n| Vehicle pursuit (10-80)   | $3,000  | 2 hours   |\n| Drug sale/trafficking     | $3,000  | 2 hours   |\n| Shooting                  | $7,500  | 2 hours   |\n| Officer-involved shooting | $10,000 | 3 hours   |\n\n# 12. Patrol and Communications\n\n## Radio Channels\n\n| Channel   | Purpose                |\n| --------- | ---------------------- |\n| Channel 1 | Active LSPD radio      |\n| Channel 2 | EMS                    |\n| Channel 3 | Busy / writing reports |\n| Channel 4 | Active training        |\n| Channel 5 | DOJ                    |\n\n## Radio Rules\n\n- Avoid extended personal conversations.\n- Keep radio traffic clear and professional.\n- Wait 3–5 seconds after another callout before transmitting.\n- Familiarize yourself with department 10-codes.\n\n## Patrol Regulations\n\n- Follow traffic laws.\n- Treat traffic lights as stop signs.\n- Use lights and sirens appropriately.\n- Maintain proper uniforms and vehicles.\n- Respond to requests for additional units unless occupied with a report or higher-priority responsibility.\n\n## Response Codes\n\n| Code   | Meaning                              |\n| ------ | ------------------------------------ |\n| Code 1 | Normal response, no emergency lights |\n| Code 2 | Emergency lights, no sirens          |\n| Code 3 | Emergency lights and sirens          |\n\n# 13. Scene Conduct and T-Count – Section 12\n\n- Officers must match the opposing side's force.\n- PD should maintain an equal T-count or have no more than one additional officer.\n- Normal maximum T-count: 8 officers.\n- Panic buttons and 10-99 calls are exceptions.\n- A minimum of 5 officers on duty is required for gang-block calls.\n- Officers must never respond to gang-block calls solo.\n- For 10-99 situations, there is no maximum officer count.\n\n## T-Count Reference\n\n| Situation                    | T-count                      |\n| ---------------------------- | ---------------------------- |\n| Officer in distress          | No maximum                   |\n| Prison transport             | Minimum 5 officers on duty   |\n| Other heists                 | Maximum 8                    |\n| Fleecas                      | Maximum 8                    |\n| Gang vs. gang shootouts      | Maximum 15                   |\n| House/store/bank truck/cargo | Maximum 8                    |\n| Gang-block calls             | Minimum 5 on duty; maximum 8 |\n| Vehicle pursuits             | See pursuit limits           |\n| Traffic stops                | Maximum 6                    |\n| Felony stops                 | Maximum 10                   |\n| Other scenes                 | Maximum 8                    |\n\n## Pursuit Vehicle Limits\n\n| Pursuit status | Maximum vehicles | Maximum officers alive |\n| -------------- | ---------------- | ---------------------- |\n| Code Green     | 3                | 6                      |\n| Code Yellow    | 4                | 8                      |\n| Code Red       | 5                | 8                      |\n\nThe 2026 T-count announcement also confirms that the standard maximum is 8, with exceptions for panic buttons and 10-99 calls.\n\n# 14. Traffic Stops – Section 13\n\n- Traffic stops are for road violations and other appropriate reasons.\n- Activate lights and sirens to signal the driver.\n- Once stopped, turn off sirens but keep lights flashing.\n- Officers must formally introduce themselves.\n- Request the driver's license, registration and insurance.\n- Check the driver's information and outstanding warrants.\n- Check whether the vehicle is stolen.\n- Officers may issue a warning or ticket when appropriate.\n- Tickets must be roleplayed and entered using the correct fine command.\n- Additional units may be requested when a vehicle or occupant presents a reasonable concern.\n- Only one additional unit should respond to a routine traffic-stop backup request.\n\n# 15. Code 5 Felony Stops – Section 14\n\n- A Code 5 stop requires probable cause.\n- Additional units should be requested.\n- Officers must coordinate through radio.\n- The primary officer directs the stop.\n- Officers must ensure that all occupants are accounted for.\n- The vehicle is checked after occupants are secured.\n\n## MDT Vehicle BOLOs – Section 14.2\n\n- Vehicle BOLOs last a maximum of 30 minutes.\n- Proper RP interaction is required before issuing one.\n- Valid reasons include:\n  - Losing sight of a vehicle during a 10-80.\n  - Vehicle involvement in shots fired.\n  - Vehicle involvement in a bank robbery.\n  - Confirmed drug sales.\n- BOLOs must be deleted or checked after 30 minutes.\n\n# 16. Vehicle Pursuits – Section 15\n\n## General Rules\n\n- Officers must prioritize public safety.\n- Dispatch must be informed when a 10-80 begins.\n- Provide vehicle description, occupancy, location and direction.\n- Officers involved in crashes must report them.\n- Pursuits are not races.\n- Maintain assigned positions and communicate when changing positions.\n\n## Pursuit Positions\n\n| Position  | Responsibilities                                       |\n| --------- | ------------------------------------------------------ |\n| Primary   | Leads the pursuit                                      |\n| Secondary | Maintains communication and callouts                   |\n| Tertiary  | Supports the pursuit and monitors outside interference |\n| Air-1     | Takes over callouts when active                        |\n\n## Section 15.4 – PIT Policy\n\n- PIT maneuvers require confirmed Code Yellow.\n- Senior Officer+ or the highest-ranking active officer must confirm the status.\n- City maximum: 100 MPH.\n- Highway/freeway/bridge maximum: 140 MPH, subject to pursuit status.\n- A one-minute PIT timer is required.\n- The timer may be requested 30 seconds after Code Yellow.\n- A 30-second cooldown applies between PIT attempts.\n- The highest-ranking officer on duty must authorize the timer.\n\n## Pursuit Codes\n\n| Code        | Meaning                                                                                         |\n| ----------- | ----------------------------------------------------------------------------------------------- |\n| Code Green  | Three strikes have not been completed; spike strips are permitted                               |\n| Code Yellow | Three strikes have been given; PIT authorization becomes available after the timer              |\n| Code Red    | Suspect demonstrates lethal intent or a serious threat; matching deadly force may be authorized |\n\nOther rules:\n\n- Code Orange was removed in the June 2026 announcement.\n- The updated PIT timer applies after all three strikes.\n- Outside vehicles interfering with a pursuit may also receive pursuit codes.\n- Pursuit cooldown: 30 minutes to locate suspects or vehicles.\n- Reasonable suspicion is required before further action.\n\n## Air-1 – Pursuits\n\n- Air-1 must have a co-pilot.\n- Air-1 takes over pursuit callouts when active.\n- The co-pilot is responsible for communications.\n\n# 17. Foot Pursuits – Section 17\n\n- Officers must follow the foot-pursuit SOP.\n- Verbal warnings are required.\n- Taser and tackle policies apply.\n- Cuffing is permitted when a suspect is appropriately secured.\n- Special rules apply when suspects reach for weapons or enter water.\n- Officers must use appropriate equipment and follow department safety requirements.\n\n# 18. Boat Pursuits – Section 18\n\n- Officers must use a police boat.\n- Jet skis are prohibited.\n- Ramming with boats or jet skis is prohibited.\n- Police may commission boats when the situation requires it.\n\n# 19. Green Zones – Section 19\n\n## Green Zone Locations\n\n- Mall.\n- Whitelisted businesses.\n- Official server events.\n- Houses and apartments.\n- Hospital.\n- Courthouse.\n- Gyms.\n- Arena.\n- Civilian jobs.\n- Cayo Bridge.\n\n## Green Zone Rules\n\n- Officers cannot initiate interactions inside Green Zones unless a law has been broken.\n- Exception: Trespassing at whitelisted businesses or the hospital.\n- Officers cannot serve warrants inside Green Zones.\n- Officers cannot camp Green Zones.\n- Officers may respond to dispatch calls inside Green Zones.\n- Police cannot initiate gunfire inside Green Zones.\n- Police may return fire if shot at.\n- If an interaction begins outside a Green Zone and continues inside, normal RP may continue.\n- Bodycam must document that the interaction began outside the Green Zone.\n- Major city rule violations must be documented with bodycam and reported through a ticket.\n- Officers must not take matters into their own hands.\n\n# 20. Gang vs. Gang Scenes\n\nRestricted to gang blocks\n\nThe original change announcement and current SOP both establish special rules for gang shootouts.\n\n## General Requirements\n\n- Gang vs. gang scenes are restricted to gang blocks.\n- Officers must prioritize officer safety.\n- PD must secure the scene.\n- Gangs must be separated by color.\n- Injured and deceased individuals are included in scene management.\n- Weapons must not be confiscated under the special gang-scene procedure.\n- Officers should contact Detectives or collect relevant evidence when possible.\n\n## Gang Scene Fines\n\nThere is a discrepancy between the two documents:\n\n- December 2025 announcement: $20,000 per member for Gang Related Shooting.\n- Current SOP: $50,000 per member for Gang Related Shooting.\n\nThe current SOP lists $50,000.\n\nThe original announcement also specifies that officers should not make arrests or incidents unless suspects shoot or rob after the specified two-minute period. The current SOP does not repeat that exact restriction.\n\n# 21. Hostage Situations\n\n## Primary Objective\n\n- Preservation of life is the highest priority.\n- Hostage safety takes precedence over immediate suspect apprehension.\n- Officers must allow realistic and fair roleplay.\n\n## Initial Response\n\n- Establish a perimeter.\n- Assign a primary negotiator.\n- Maintain controlled radio communications.\n- Allow the situation to develop naturally.\n\n## Negotiations\n\n- Negotiations must be conducted in good faith.\n- Suspect demands must be taken seriously.\n- Officers cannot intentionally stall negotiations for tactical advantages.\n- Communication must remain professional and in character.\n\n## Hostage Demands\n\n- One demand per hostage.\n- Maximum of three demands per scene.\n- Physical item exchanges are prohibited.\n- Acceptable demands include safe passage and reasonable time allowances.\n- Unrealistic demands should be negotiated down rather than immediately denied.\n\n## Prisoner Transport and Life-for-Life\n\n- Sergeant+ officers have discretion to approve or deny prisoner transports as hostage demands.\n- Decisions must consider officer headcount and city call volume.\n- Prison transports and Life-for-Life exceptions are restricted to Gang Captain+.\n\n## Use of Force During Hostage Situations\n\n- Force is a last resort.\n- Lethal force requires lethal intent.\n- Tactical escalation must be justified by the RP.\n- The highest-ranking officer on scene must approve major tactical escalation.\n- Officers should not rush negotiations.\n- Force should not be initiated while a weapon is actively aimed at a hostage unless reasonable options have been exhausted.\n\n# 22. Responding to Calls – Section 21.2\n\n## Priority Chart\n\n1. Officer in distress.\n2. Prison transport.\n3. Heists.\n4. Hostage situations.\n5. Gang vs. gang violence.\n6. Multiple shots fired (more than two).\n7. House/store robberies, bank trucks and cargo boats.\n8. All other calls.\n\nOfficer in distress:\n\n- All officers must prioritize responding.\n- Officers processing suspects in cells are the exception.\n- If multiple officers are processing, the lowest-ranking officer should remain to finish processing.\n\n# 23. SWAT Activation – September 2026 Update\n\nLatest dated announcement in the change log\n\n| Activation type | Minimum operators |\n| --------------- | ----------------- |\n| Casual SWAT     | 3                 |\n| Full SWAT       | 4                 |\n\nSWAT activation must follow the updated personnel thresholds and chain of command.\n\n# 24. LSPD and FIB Jurisdiction – Section 21.3\n\nThe current SOP includes a specific jurisdictional policy:\n\nIndependent Governance\n\n- LSPD is an independent governing body.\n- FIB has no supervisory authority over LSPD personnel or departmental operations.\n\nJoint Investigations\n\n- LSPD assistance to FIB during an investigation is considered a joint operation.\n- LSPD officers take orders exclusively from the highest-ranking LSPD officer involved or present.\n- FIB agents may request assistance and coordination.\n- LSPD should assist when possible.\n- If an LSPD operation or warrant results in an incident involving an injured or attacked FIB agent, the underlying case remains under LSPD jurisdiction.\n\nConduct\n\n- Mutual respect between departments is mandatory.\n- Insubordination, disrespect or overstepping jurisdictional boundaries must be documented and reported to LSPD High Command.\n\n# 25. Important Changes and Conflicting Rules\n\nAfter comparing both documents, these are the areas that need clarification from Command.\n\n| Topic              | Change announcement                                               | Current SOP                                                                               | What needs clarification                                     |\n| ------------------ | ----------------------------------------------------------------- | ----------------------------------------------------------------------------------------- | ------------------------------------------------------------ |\n| Maximum jail time  | 200 months                                                        | 200 months, but another paragraph says 180 months or recommended time, whichever is lower | Confirm whether 180 or 200 is the actual discretionary limit |\n| Gang shooting fine | $20,000                                                           | $50,000                                                                                   | Confirm $50,000 is the replacement                           |\n| Expungements       | Initially transferred to DOJ, later returned to PD temporarily    | PD handles expungements                                                                   | Confirm when DOJ takes over                                  |\n| In-city warrants   | Specific attempted/murder charges involving officers or civilians | Broader criminal charges, with an exclusion for attempted murder of a government official | Clarify eligible charges                                     |\n| Green Zones        | No interactions initiated inside                                  | Cannot initiate unless a law has been broken, with specific exceptions                    | Clarify which violations permit intervention                 |\n| T-count            | Maximum 8, with exceptions                                        | Maximum 8, gang shootouts up to 15                                                        | Confirm the gang-scene exception                             |\n| PIT                | Code Orange removed; updated timer                                | Code Orange still appears in older pursuit sections                                       | Update outdated wording                                      |\n| Miranda Rights     | Required in custody                                               | Required when in custody and being questioned; processing says read once cuffed           | Clarify exact timing                                         |\n\n## 26. Additional Issues Found in the Full SOP\n\nThese aren't necessarily new changes, but they are important rules that should be included in the master reference.\n\n- Section 4.1: Reasonable suspicion allows detention but not searching.\n- Section 4.2.2: Searches require probable cause or explicit consent.\n- Section 7.1: Suspects who refuse fingerprints receive maximum penalties.\n- Section 8.1: Weapon licenses require clean records.\n- Section 10: Impound fees and vehicle hold times are specified.\n- Section 13: Traffic stops require proper introductions and documentation.\n- Section 14.2: Vehicle BOLOs expire after 30 minutes.\n- Section 15.6: Pursuit cooldown is 30 minutes.\n- Section 18: Police boats are allowed, but jet skis are prohibited.\n- Section 21.3: LSPD maintains independent jurisdiction from FIB.\n\n## 27. Historical Update Timeline\n\n| Date               | Update                                                                           |\n| ------------------ | -------------------------------------------------------------------------------- |\n| September 7, 2025  | Bodycam, scene conduct, Miranda, cuffing, fines, warrants and Green Zone changes |\n| September 7, 2025  | Search and seizure clarification                                                 |\n| September 14, 2025 | Weapon confiscation and buyback procedures                                       |\n| October 15, 2025   | Division strike requirements                                                     |\n| October 29, 2025   | Expungements transferred to DOJ                                                  |\n| October 29, 2025   | Non-lethal shotgun, shields and Air-1 rules                                      |\n| November 4, 2025   | Green Zone locations updated                                                     |\n| November 8, 2025   | Gang vs. gang scene procedures                                                   |\n| December 15, 2025  | Vehicle color permissions                                                        |\n| December 21, 2025  | Weapon rank requirements                                                         |\n| December 27, 2025  | Expungements returned to PD temporarily                                          |\n| January 28, 2026   | Gun confiscation, buyback and search warrant procedures                          |\n| February 23, 2026  | Maximum fine and jail limits updated                                             |\n| April 6, 2026      | Tackle procedure updated                                                         |\n| April 29, 2026     | Hostage SOP updated                                                              |\n| May 14, 2026       | Additional SOP update announced, image unavailable                               |\n| May 24, 2026       | Gang vs. gang SOP announced, image unavailable                                   |\n| June 9, 2026       | Code Orange removed and PIT policy updated                                       |\n| June 18, 2026      | T-count clarification                                                            |\n| July 28, 2026      | Prisoner transport and buyback rules                                             |\n| September 7, 2026  | SWAT activation requirements                                                     |\n\nThe timeline is based on the supplied announcement dates. The full SOP document itself lists its latest revision date as June 5, 2026.\n\n# Final Summary – What Officers Should Know\n\nThese are the most important policies to remember:\n\n1. Minimum activity is 5 hours weekly.\n2. Three active strikes disqualify officers from divisions.\n3. Bodycams must be active and footage must be retained.\n4. Searches require probable cause or explicit consent.\n5. Miranda Rights must be read according to custody and questioning requirements.\n6. Hard cuffs are a last resort.\n7. Hard cuffs, power cuffing and equipment abuse can result in strikes.\n8. All confiscated weapons require MDT reports and Dyno logs.\n9. Only eligible F9 weapons can be bought back.\n10. Search warrants must be signed before house breaches.\n11. Warrants cannot be served inside Green Zones.\n12. Standard T-count is 8 officers, subject to listed exceptions.\n13. Gang-block calls require at least 5 officers on duty.\n14. Gang vs. gang scenes have special procedures.\n15. Code Orange has been removed.\n16. Code Yellow is required for PIT authorization.\n17. Hostage negotiations must be conducted in good faith.\n18. SWAT requires 3 operators for casual activation and 4 for full activation.\n19. LSPD maintains its own chain of command separate from FIB.\n20. The maximum fine is $200,000 and the maximum sentence is generally 200 months, subject to the sentencing discrepancy noted above.\n\nSource documents: Original SOP change announcements&#x20;\n\nPasted text(4).txt\n\n&#x20;and current Backstreets Police Department SOP&#x20;\n\nPasted text(5).txt\n\n.\n\n\n\nOne final note: The May 14 and May 24 announcements contain images rather than readable text in the supplied change log. Their contents aren't included here, so those two updates still need to be checked against the original Discord announcements.\n\nThis is the consolidated master reference from both supplied documents, rather than a guarantee that every rule is free of contradictions.\n\n\n# 26. H.E.A.T. Division – Highway Enforcement of Aggressive Traffic\n\n## Mission Statement\n\nThe H.E.A.T. Division is responsible for professional vehicle pursuit operations, traffic enforcement, and the safe apprehension of fleeing suspects.\n\n## Entry Requirements\n\n- Must hold the rank of Senior Officer or above.\n- Must have held Senior Officer rank for at least one week.\n\n## Division Structure\n\n### H.E.A.T. Operator\n\n- Completed full H.E.A.T. training.\n- Demonstrates expected pursuit and vehicle knowledge.\n- Vehicle: Marked Charger with ram bar.\n\n### H.E.A.T. Senior Operator\n\n- Outstanding performance and professionalism.\n- Subject to performance monitoring and IA review.\n- Vehicles: Unmarked Charger or Raptor with ram bar.\n\n### H.E.A.T. Supervisor\n\n- Oversees operators and conducts training.\n- Responsible for supervision and performance.\n- Vehicles: Unmarked Charger, Raptor, or Escalade with ram bar.\n\n### H.E.A.T. Command\n\n- Oversees daily operations and training systems.\n- Authorized to modify division protocols.\n- Vehicle: All authorized division vehicles.\n\n## Authorized Modifications\n\n- Tuner chip.\n\n## Training Process\n\n### Part 1 – Prior Knowledge Test\n\n- PIT requirements.\n- Vehicle knowledge.\n- 10-80 knowledge.\n- Utility knowledge.\n\n### Part 2 – Trainee Demonstration\n\n- Successful callouts.\n- Demonstration of pursuit knowledge.\n- Proper use of authorized equipment.\n\n### Part 3 – Pursuit Drill\n\n- Demonstrate professional pursuit judgment.\n- Trainer plays the suspect.\n- Evaluation of communication, safety, and coordination.\n\n### Part 4 – Knowledge Recap\n\n- What does H.E.A.T. stand for?\n- When is a PIT authorized?\n- What restrictions apply to PIT maneuvers?\n- Who can authorize a PIT maneuver?\n\n## Tactical Definitions\n\n**PIT Maneuver:** A Pursuit Intervention Technique used in roleplay to stop a fleeing vehicle. All use must follow division authorization requirements and server rules.\n\n**Spiking:** Deployment of a tire-deflation device in approved roleplay situations.\n\n**Roadblocks:** Police traffic-control blockades used for approved operational and event purposes.\n\n## Tactical Deployment Protocols\n\n- H.E.A.T. units receive primary pursuit responsibility when assigned.\n- The initiating officer normally transitions to secondary.\n- Supervisors retain authority over pursuit management.\n- Units must maintain professional radio communication.\n- Tactical decisions must follow server policies and supervisory authorization.\n\n## Supervisor Oversight\n\nH.E.A.T. Supervisors and Command are responsible for:\n\n- Monitoring pursuits.\n- Calling off pursuits when necessary.\n- Approving authorized tactics.\n- Reassigning or removing units when necessary.\n\n## Advancement to Senior Operator\n\n- Must be an active H.E.A.T. Operator for at least two weeks.\n- Must demonstrate exceptional performance and professionalism.\n- Must be selected by Command for the Senior Operator evaluation.\n\n## Evaluation Criteria\n\n- Safety.\n- Communication.\n- Judgment.\n- Professionalism.\n- Roleplay quality.\n- Leadership and decision-making.\n\n# 27. Air Support Division\n\n## Mission Statement\n\nThe Los Santos Police Air Support Division provides aerial assistance to ground units, supports officer and civilian safety, and conducts aerial observation, surveillance, and recovery operations.\n\n## Area of Operation\n\nAir Support operates throughout Los Santos, Sandy Shores, and Paleto Bay.\n\nOperators must demonstrate proficiency in operating aircraft across different environments.\n\n## Training Structure\n\nOperators must complete five training phases.\n\n### Phase 1 – Basic Flight Operations\n\n- Basic flight controls.\n- Takeoffs.\n- Landings.\n- Land navigation.\n- Responding to calls efficiently.\n\nTraining is conducted alongside a certified Flight Instructor.\n\n### Phase 2 – Camera Operation\n\nOperators must understand the three camera systems aboard Air-1.\n\n**Surveillance Camera**\n\n- Vehicle plate identification.\n- Vehicle make and model identification.\n- Identifying points of interest.\n- Relaying information to ground units.\n\n**Night Vision**\n\n- Used during nighttime and low-light operations.\n- Supports aerial observation and tracking.\n\n**Thermal Vision**\n\n- Infrared observation.\n- Assists in locating individuals in covered outdoor environments.\n- Operators must understand its limitations.\n\n### Phase 3 – Vehicle Chases\n\n- Respond to traffic stops.\n- Assist ground units with vehicle identification.\n- Maintain aerial observation.\n- Relay relevant information to ground units.\n- Follow Air Support visibility and tracking policies.\n\nIf visual contact is lost for more than 10 seconds, the operator must follow the established visual-search procedure.\n\n### Phase 4 – Rescue and Recovery Missions\n\n- Coordinate with relevant agencies.\n- Locate missing individuals.\n- Assist with recovery missions.\n- Demonstrate knowledge of aircraft rescue equipment.\n\n### Phase 5 – Final Evaluation\n\n- Demonstrate overall flight proficiency.\n- Demonstrate camera knowledge.\n- Demonstrate communication skills.\n- Demonstrate rescue and recovery knowledge.\n\n# 28. K-9 Division\n\n## 1. Responsibilities\n\n- Provide canine support to patrol, investigations, and special operations.\n- Maintain professionalism and follow server rules.\n- Ensure public and officer safety during deployments.\n\n## 2. Organizational Structure\n\n- K-9 Division Director – Overall leadership and policy approval.\n- K-9 Assistant Director – Assists the Director and oversees training.\n- K-9 Supervisor – Manages handlers and deployments.\n- K-9 Senior Handler – Experienced handler who mentors others.\n- K-9 Handler – Certified officer assigned to an approved K-9.\n\n## 3. On-Duty and Off-Duty Units\n\n- K-9 callsigns may only be used while on duty with an approved dog.\n- Off-duty handlers must return to standard patrol.\n- Major scene deployments require supervisory approval.\n\n## 4. Vehicles and Uniforms\n\n- Only approved K-9 vehicles may be used.\n- One additional officer may ride in the front passenger seat.\n- Uniforms must follow department guidelines.\n- K-9s must remain in designated vehicle areas.\n\n## 5. K-9 Acquisition\n\n- Handlers may request a K-9 through the Director or Assistant Director.\n- Dogs must reach Level 5 before deployment.\n\n## 6. Training\n\n- Supervisor certification is required before patrol.\n- Ongoing obedience, tracking, and search training is encouraged.\n- Scenario refreshers are recommended every 30 days.\n\n## 7. K-9 Health and Maintenance\n\n- Feed and water the K-9 through RP.\n- Use `/k9heal` for medical RP.\n- Use `/k9armor` when appropriate.\n- Ensure the dog receives adequate rest.\n\n## 8. Commands\n\n| Command | Description |\n| --- | --- |\n| `/k9` | Opens main menu |\n| `/k9spawn` | Spawns assigned K-9 |\n| `/k9vehicle` | Loads/unloads K-9 |\n| `/k9follow` | Dog follows handler |\n| `/k9trackall` | Tracks available scent |\n| `/k9trackplayer` | Tracks specific player |\n| `/k9searchcar` | Searches vehicle |\n| `/k9searchped` | Searches pedestrian |\n| `/k9heal` | Heals K-9 (RP) |\n| `/k9armor` | Gives vest/armor |\n| `/k9feed` | Feeds dog |\n| `/k9fetch` | Plays fetch |\n| `/k9ball` | Plays fetch |\n| `/k9bark` | Commands dog to bark |\n| `/k9sit` | Commands dog to sit |\n| `/k9carry` | Picks up/carries dog |\n| `/k9camera` | Views dog-mounted camera |\n| `/k9mount` | Mounts camera |\n\nCamera use must be restricted to legitimate RP scenarios. OOC scouting is prohibited.\n\n## 9. Radio Procedures\n\n- K-9 units identify themselves as K-9 on radio.\n- Example: K-9-12.\n- Notify dispatch when deploying, tracking, or operating with a K-9.\n\n## 10. Loading and Unloading\n\n- K-9 must be spawned at the station before patrol.\n- Use the appropriate commands to load and unload.\n- Maintain traffic safety when opening vehicle doors.\n\n## 11. Suspect Transport\n\n- K-9 units cannot transport suspects.\n- Request another patrol unit for transport.\n- Keep the dog secured until transport arrives.\n\n## 12. K-9 Bite Response\n\n- Give a verbal warning before deployment unless an immediate lethal threat exists.\n- Provide appropriate RP first aid following a bite.\n- Notify the K-9 Supervisor.\n- Handlers remain accountable for their dog's actions.\n\n## 13. 10-11 Traffic Stops\n\n- Deploy only when a threat is detected or a sniff is requested.\n- Keep the dog secured unless deployment is necessary.\n\n## 14. Unarmed Suspects\n\n- K-9s cannot be used against compliant or surrendering subjects.\n- Deployment is restricted to situations permitted by division policy.\n\n## 15. 10-70s and 10-80s\n\n- K-9s may assist with foot or bicycle pursuits and vehicle bailouts when appropriate.\n- Announce deployments over radio.\n\n## 16. Civilian Interaction\n\n- Civilian interaction requires handler approval.\n- Keep the leash on.\n- Avoid aggressive RP with civilians.\n\n## 17. K-9 Searches\n\n- Request consent or warrant RP when appropriate.\n- Searches may involve vehicles, people, and property.\n- Common deployments include burglary, vehicle theft, narcotics, weapons, and wanted-person investigations.\n\n## 18. Tracking Abilities\n\n- Use `/k9trackplayer` or `/k9trackall`.\n- Maintain radio communication.\n- Stop tracking when the scene becomes unsafe.\n\n# 29. Detective Division\n\n## Mission Statement\n\nThe Detective Division consists of criminal investigators who gather evidence, conduct interviews, examine records, observe suspects, and participate in investigations, warrants, raids, and arrests alongside local, state, judicial, and federal agencies.\n\n## Entry Requirements\n\n- Must hold Senior Officer rank or above.\n- Above-average RP rating.\n- Willingness to conduct extended roleplay.\n- Must complete all Rookie Evaluation phases within two weeks of acceptance.\n\n## Division Structure\n\n### Unit Chief / Unit Lead\n\n- Oversees all detectives.\n- Establishes policies and procedures.\n- Maintains division standards.\n- Supervises applications and onboarding.\n\n### Detective First Grade\n\n- Ensures compliance with division policies.\n- Trains new detectives.\n- Coordinates with other agencies.\n\n### Detective / Senior Detective\n\n- Handles investigations.\n- Gathers evidence.\n- Writes reports.\n- Participates in warrants and operations.\n\n### Detective Trainee (DT)\n\n- Works under an assigned Detective.\n- Participates in ride-alongs.\n- Evaluated on investigative and RP performance.\n- Cannot drive Detective vehicles or operate independently without authorization.\n\n## Crime Scene Investigation (CSI)\n\nCSI operates under the Detective Division and handles crime scene documentation and forensic evidence.\n\n### CSI Duties\n\n- Secure crime scenes.\n- Photograph and document scenes.\n- Collect physical evidence.\n- Maintain chain of custody.\n- Prepare forensic reports.\n- Coordinate with EMS when applicable.\n- Digitally recreate scenes when available.\n\n### Requirements\n\n- Must be a Full Detective.\n- Must demonstrate attention to detail, patience, and professionalism.\n\nDetectives must complete a CSI assignment before joining another Detective specialization.\n\n## Vehicle Guidelines\n\n**Detective First Grade**\n\n- Any unmarked vehicle.\n- Interior lights must be visible.\n- Either approved UC vehicle.\n\n**Senior Detective**\n\n- Slicktop with doortag.\n- All-black or grey.\n- Interior lights must be visible.\n\n**Detective**\n\n- Slicktop with livery and doortag.\n- All-black or grey.\n\n**Allowed Vehicles**\n\n- Any fleet vehicle or F9 vehicle that follows division guidelines.\n\n**Detective Trainee**\n\n- Cannot use Detective Division vehicles.\n- Must ride with a Full Detective or higher.\n- Cannot go active without a Full Detective on duty.\n\n## Uniform Guidelines\n\n### Full Detectives – Professional Attire\n\n- Professional EUP clothing.\n- Visible badge.\n- Button-up or polo in professional colors.\n- Optional suit jacket or tie.\n- Slacks or matching khakis.\n- Dress shoes or black duty shoes.\n\n### Plain Clothes\n\n- May be used for intelligence gathering, surveillance, or blending in.\n- Jeans or similar pants must not be baggy or sagging.\n- T-shirts and sweatshirts are permitted.\n- Hats and casual shoes are permitted.\n- Badges must be removable.\n\nDetectives must not patrol in plain clothes unless responding to a case.\n\n### Prohibited Items\n\n- Jewelry other than a wristwatch.\n- Unprofessional haircuts or wild colors.\n- Visible gang-related tattoos.\n- Messy facial hair.\n- Face coverings.\n\n### Detective Trainees\n\n- Not authorized to use EUP.\n- Must use standard on-duty loadouts and uniforms.\n\n## Weapons and Equipment Guidelines\n\n### Standard Loadout\n\n- 1 Camera.\n- 1 Evidence Pouch.\n- 1 Flashlight.\n- 1 Taser.\n- 1 Combat Pistol.\n- 1 AR.\n- 1 SMG.\n\nReminder: Lock your vehicles at all times.\n\n## Daily Operations\n\nDetectives handle:\n\n- LEO-requested crime scene investigations.\n- Criminal intelligence gathering.\n- Reports and known-offender research.\n- Sting and raid planning.\n- Support for Q.R.T.\n- Inter-agency undercover assignments.\n\nAll raid and sting operations require coordination and permission from the Unit Lead or higher.\n\n## Specializations and Certifications\n\n### Crime Scene Investigation (CSI)\n\n- Requires specialized training.\n- Approval from Detective First Grade or higher.\n- First certification available to detectives.\n- Handles evidence collection and forensic reports.\n\n### Aerial Surveillance Team (AST)\n\n- Requires specialized training.\n- Approval from Detective First Grade or higher.\n- Provides aerial observation and surveillance support.\n\n### Gang and Narcotics Team (GNT)\n\n- Requires specialized training.\n- Approval from Unit Leader or higher.\n- Handles gang and narcotics investigations.\n- Conducts intelligence gathering and coordinates with other units.\n\n### Homicide and Robbery Team (HRT)\n\n- Requires specialized training.\n- Approval from Unit Leader or higher.\n- Handles homicide and robbery investigations.\n- Conducts interviews and evidence collection.\n\n## Application and Training Process\n\n- Submit an application to the Detective Division.\n- Selected applicants undergo evaluation.\n\n### Evaluation Criteria\n\n- RP intentions and professionalism.\n- Conduct and communication with superiors.\n- Case handling and time management.\n- Average case length of 1–4+ hours.\n- Depth of roleplay.\n- Completion of training.\n\nSuccessful completion determines advancement to Full Detective.\n\n**Policy Reminder:** Policies and procedures may change. Detectives should regularly check updates from their chain of command.\n\n# 30. Motorcycle Unit (M.C.U.)\n\n## Purpose\n\nThese SOPs establish guidelines for the safe and effective operation of the Motorcycle Unit.\n\nThe MCU is responsible for:\n\n- Traffic enforcement.\n- Crowd control.\n- Emergency calls.\n- Escort duties.\n- Special events.\n- Evidence and prison transports.\n- Backup assistance.\n\n## 1. Uniform and General Appearance\n\n- Appropriate MCU uniform is required when operating a police-issued motorcycle.\n- This includes emergency import motorcycles.\n- Jewelry is prohibited while operating a motorcycle.\n- Uniform requests should be directed to Solo KJS or John Johnson.\n\n## 2. Motorcycle Pre-Operation Checklist\n\nBefore starting patrol:\n\n- Ensure the motorcycle has the appropriate livery.\n- Enable all required extras.\n- Fully repair and refuel the motorcycle.\n- Set up radars and plate readers before leaving the MRPD garage.\n\n## 3. General Traffic Conduct\n\n- Follow all traffic laws.\n- No wheelies, stoppies, or dangerous tricks.\n- City speed limit: 80 MPH.\n- Highway/freeway speed limit: 120 MPH.\n- Wait the required three seconds at red lights.\n- Lane-splitting is permitted when necessary and with extreme caution.\n\n## 4. Escort Duties\n\n- MCU operators must assist with escort duties when needed.\n- Report suspicious or unusual activity ahead.\n- Minimum of two MCU operators.\n- Maximum of four MCU operators.\n- Follow the approved escort formation.\n\n## 5. Crowd Control\n\nMCU operators may assist with:\n\n- Parades.\n- Crime scene perimeters.\n- Clearing loitering individuals from government buildings.\n\nAll crowd-control activities must follow department use-of-force SOPs.\n\n## 6. Backup Calls\n\n- Unless the MCU operator is the first or second unit on scene, their main responsibility is perimeter establishment.\n- During a 10-99, respond according to normal emergency procedures.\n\n## 7. Numbers and T-Count\n\nOnly one MCU operator is permitted per scene, including 10-80 and 10-19 situations.\n\nExceptions:\n\n- Escort duties.\n- 10-99 situations.\n\n### Required Four-Door Units Per MCU Operator\n\n| Four-Door Units on Patrol | MCU Operators Allowed |\n| --- | --- |\n| 0–1 | 0 |\n| 2–3 | 1 |\n| 4–5 | 2 |\n| 6–7 | 3 |\n| Additional units | One additional MCU per two additional four-door units |\n\nDuring a 10-80, MCU operators must remain at the rear of the pursuit unless the target is another motorcycle.\n\nAn MCU operator may temporarily take over if the primary unit crashes or loses visual contact, until the primary unit can resume responsibility.\n\n## 8. 10-80 and Arrest Procedures\n\n- Follow department pursuit procedures.\n- Request a four-door unit for suspect transport after an arrest.\n- MCU operators remain the arresting officers.\n- Complete the required arrest report as usual.\n\n# 31. General Division Policy\n\nAll divisions are expected to:\n\n- Follow LSPD department-wide SOPs.\n- Maintain professional conduct.\n- Follow their division's chain of command.\n- Maintain proper radio communication.\n- Follow server rules and roleplay standards.\n- Cooperate with Internal Affairs when required.\n- Keep division policies and training requirements updated.\n\n\n# 32. Internal Affairs Division\n\n**Backstreets Police Department – Internal Affairs Division**  \n**Standard Operating Procedures**  \n**Restricted:** Internal Affairs Oversight and Commander of Internal Affairs only\n\n## Mission\n\nThe Internal Affairs Division (IA) protects the integrity of the Backstreets Police Department by investigating complaints of misconduct, SOP violations and PD corruption by department personnel. IA exists to keep the department accountable to the public, to protect officers from false accusations, and to make sure discipline is applied fairly and consistently under the Strikes & Sanction Guide.\n\nThese SOPs work alongside the Backstreets Police Department SOPs. They do not replace them, and neither is above the Backstreets City bible.\n\n## 1. Scope and Authority\n\n### 1.1 What IA Investigates\n\n- Complaints from civilians, lawyers, the DOJ or other agencies about LSPD personnel.\n- SOP violations listed in the Strikes & Sanction Guide (Class 1, Class 2 and Class 3 conducts).\n- PD corruption, including abuse of position, bribery, mishandling or \"losing\" evidence, unlogged gun buybacks, and breaching a house without a signed search warrant.\n- Unlawful use of force, power cuffing, taser abuse and hard cuff abuse.\n- Off-duty conduct that reflects on the department (SOP 1.4).\n- Officer-involved shootings and any scene where an officer's actions are formally questioned.\n- Conflicts with other agencies, including FIB, documented under SOP 21.3.\n\n### 1.2 What IA Does Not Handle\n\n- Out-of-character (OOC) and city rule breaks such as failed RP, NVL or metagaming. These go to a Government/staff ticket, as stated in the LSPD SOPs.\n- Routine supervisor discipline such as verbal warnings or small corrections in the field. Supervisors handle these, and IA only steps in if the matter is escalated or repeated.\n- Criminal cases against civilians. These belong to patrol, Detectives and the DOJ.\n\n### 1.3 Authority\n\nIA investigators may request bodycam footage, MDT reports, logs and statements from any LSPD member. Every officer is required to cooperate with an IA investigation. Refusing to cooperate, lying to IA, or deleting or withholding evidence is a separate violation and will be treated as Insubordination or PD corruption depending on severity.\n\nIA investigates and recommends. Discipline is issued through the chain of command, and removal-level outcomes require High Command review.\n\n## 2. Structure and Chain of Command\n\n| Position | Discord Role | Responsibilities |\n|---|---|---|\n| Commander of Internal Affairs | Commander Of Internal Affairs | Runs the division. Assigns cases, approves findings, signs off on every closed case, and reports to High Command and the Commissioner. |\n| IA Investigator | Internal Affairs Oversight | Opens and works assigned cases, collects evidence, takes statements and writes the case file and recommended finding. |\n| High Command | LSPD \\| High Command | Reviews and votes on demotions, terminations and removal-level findings. Hears appeals. |\n| Commissioner | UD \\| COMMISSIONER | Handles IA cases involving Chiefs or the Commander of Internal Affairs. |\n\n### 2.1 Joining Internal Affairs\n\n- Must be Supervisor rank (Corporal) or higher.\n- Must have zero active strikes and no sustained IA finding in the last 30 days.\n- Must be approved by the Commander of Internal Affairs.\n- Must read and acknowledge these SOPs before being given the Internal Affairs Oversight role.\n\n## 3. Code of Conduct for IA Personnel\n\n### 3.1 Confidentiality\n\n- Case details are discussed only in the Internal Affairs channels or IA voice. Never in general, command or HC channels, DMs to the subject, or in-city over radio.\n- Complainant identities are protected. The subject officer is told what the allegation is, not who reported it, unless the complainant agrees.\n- Leaking case information is grounds for immediate removal from IA and will be handled as Conduct Unbecoming of an Officer.\n\n### 3.2 Conflict of Interest\n\nAn investigator must step off a case and tell the Commander of IA if they:\n\n- Were involved in the incident or witnessed it.\n- Are in the subject officer's direct chain of command, division, or close friend group.\n- Have an open complaint or prior conflict with the subject officer or complainant.\n\nCases involving IA members are handled by the Commander of IA. Cases involving the Commander of IA or a Chief go to the Commissioner.\n\n### 3.3 Professionalism\n\nIA investigates facts, not people. Investigators must stay neutral, avoid assuming guilt, and treat subject officers, complainants and witnesses with respect. IA is not a punishment tool, and opening a case to target or harass an officer is itself misconduct.\n\n## 4. Receiving Complaints\n\n### 4.1 Complaint Sources\n\n- Officer Complaints ticket in the LSPD Discord (civilians, lawyers or officers).\n- Detective tipline reports that involve LSPD personnel.\n- Command referral: a supervisor or High Command member refers a matter to IA.\n- DOJ referral: a judge, prosecutor or lawyer raises officer misconduct during a case.\n- IA-initiated: IA may open a case on its own when there is clear evidence of misconduct, such as bodycam, MDT records or logs.\n\n### 4.2 Minimum Information for a Complaint\n\n- Officer name or callsign (or a description if unknown).\n- Date, time and location of the incident.\n- What happened.\n- Any evidence: clips, screenshots, MDT report numbers.\n\nComplaints with no evidence are still logged, but they may be closed as Not Sustained if no evidence can be found.\n\n### 4.3 Intake Steps\n\n1. Acknowledge the complaint within 24 hours and tell the complainant it is under review.\n2. The Commander of IA reviews it and either opens a case, refers it to the officer's supervisor (minor matter), or declines it (OOC matter or no allegation of misconduct).\n3. If opened, assign a case number and a lead investigator.\n\n## 5. Opening a Case\n\n### 5.1 Case Numbers\n\nEvery case is numbered IA-YEAR-###, in order, starting at 001 each year (for example, IA-2026-001).\n\n### 5.2 Case File Location\n\n- Every case gets its own thread in #ia-sealed-files, named \"IA-2026-### | Callsign\".\n- Use the pinned IA Case File Template in #ia-sealed-files. Fill in both parts.\n- All evidence, notes and statements for the case are posted in that thread only.\n\n### 5.3 Notifying the Subject Officer\n\nThe subject officer is notified within 48 hours of the case opening, unless notifying them would put evidence at risk (for example, an active corruption case). Notification includes the case number, the allegation, and when they will be asked for a statement.\n\n## 6. Investigation Procedure\n\n### 6.1 Evidence Collection\n\n- Bodycam: request footage from every officer on scene. Under LSPD SOP 2.2, bodycam must not be deleted within 24 hours of recording, so request it as early as possible.\n- MDT: pull reports, incident numbers, charges, fines and notes.\n- Discord logs: weapon confiscation, gun buyback, clock-in, LOA and strike logs.\n- Evidence stash records for any case involving seized items or weapons.\n- Radio and dispatch records where available.\n\nEvery piece of evidence is logged in the case file's Evidence Log with a link and a short description.\n\n### 6.2 Missing Bodycam\n\nAn officer who was required to have a bodycam (SOP 2.2) but cannot provide footage of the incident may face a separate SOP violation. A missing clip cannot be used as proof that the officer is innocent.\n\n### 6.3 Statements and Interviews\n\n1. Take the complainant's statement first, then witnesses, then the subject officer.\n2. Interviews are held in IA voice or in-city at HQ, with at least one IA member present. Record them if possible.\n3. The subject officer may bring one LSPD member of Supervisor rank or higher as a representative. The representative may advise but may not answer for the officer.\n4. Questions must be about the allegation. No unrelated fishing.\n5. Write a summary of each statement in the case file, with the date taken.\n\n### 6.4 Timelines\n\n| Step | Deadline |\n|---|---|\n| Acknowledge complaint | 24 hours |\n| Notify subject officer | 48 hours after case opens |\n| Subject officer statement | Within 72 hours of being requested |\n| Standard case completed | 7 days |\n| Corruption or use-of-force case completed | 14 days (extensions approved by the Commander of IA) |\n\n### 6.5 Administrative Leave\n\nFor serious allegations (Class 1 conducts, PD corruption, or officer-involved shootings under review), the Commander of IA may request that High Command place the officer on administrative leave or restricted duty while the case is open. This is not a punishment and does not count as a strike.\n\n## 7. Findings\n\nEvery case must close with exactly one finding per allegation.\n\n| Finding | Meaning | Result |\n|---|---|---|\n| Sustained | The evidence shows the violation happened. | Discipline under the Strikes & Sanction Guide. |\n| Not Sustained | Not enough evidence to prove or disprove the allegation. | No discipline. Case kept on file. |\n| Exonerated | The incident happened, but the officer acted within SOP. | No discipline. |\n| Unfounded | The allegation is false or did not happen. | No discipline. Knowingly false complaints by LSPD members may be investigated. |\n\nThe standard of proof is more likely than not, based on the evidence in the case file.\n\n## 8. Discipline\n\n### 8.1 Applying the Strikes & Sanction Guide\n\n1. Identify the Class and Section of each sustained violation (for example, Class 2 Section 11, Conduct Unbecoming of an Officer).\n2. Use the \"First Time\" penalty, or the \"Second Time or More\" penalty if the officer has an active strike for the same offense.\n3. Add any listed sanction (Probation, SUP, OAC, WTC, VA, DOC).\n4. Log every strike in the strike2 tab of the LSPD Roster. It posts to #strikes automatically and updates the officer's active strike total.\n\n### 8.2 Strike Thresholds\n\n| Active Strikes | Result |\n|---|---|\n| 2 | 48-hour suspension |\n| 3 or more | Termination or demotion, decided by High Command review. Officers in a division are removed from it (SOP 6.1). |\n| Removal-level offense | Corruption, possession of illegal items, or committing a felony: goes straight to High Command for removal. |\n\nStrikes expire as set on the strike2 tab. Expired strikes stay on the officer's record and in the IA file, and can be considered when reviewing a pattern of behavior.\n\n### 8.3 Who Issues Discipline\n\n- Strikes and minor sanctions: Commander of IA, or the officer's chain of command on IA's recommendation.\n- Suspension: Commander of IA with notice to High Command.\n- Demotion, division removal or termination: High Command vote.\n\n## 9. Closing a Case\n\n1. Lead investigator completes the case file: evidence log, statements, timeline and recommended finding.\n2. Commander of IA reviews and signs off.\n3. Subject officer is told the finding and any discipline, privately.\n4. Complainant is told the case is closed and whether it was sustained. Discipline details stay internal.\n5. Thread status is set to Closed and the thread is archived. Sealed files are never deleted.\n\n## 10. Appeals\n\n- An officer may appeal a sustained finding once, within 72 hours of being notified.\n- Appeals go to High Command, in writing, with the case number and the reason (new evidence, or the process was not followed).\n- Investigators on the original case may not vote on the appeal.\n- High Command may uphold, reduce or overturn the finding. The appeal decision is final.\n\n## 11. Records and Retention\n\n- All case files stay in #ia-sealed-files permanently, including Unfounded and Exonerated cases.\n- Only Internal Affairs Oversight, the Commander of Internal Affairs and server administrators can see sealed files.\n- Case files may be shared with High Command for discipline review or appeals, and with the DOJ only when legally requested, with approval from the Commander of IA.\n\n## 12. Special Investigations\n\n### 12.1 Officer-Involved Shootings\n\nIA may review any officer-involved shooting to confirm the use of force followed SOP 5 (Use of Force), 5.1 (Matching Force) and the lethal force conditions: imminent threat, intent and weapons present. A review is not an accusation, and most reviews will close as Exonerated.\n\n### 12.2 PD Corruption\n\nCorruption cases (Class 1 Section 1) may be investigated without notifying the subject officer until evidence is secured. Examples from the LSPD SOPs include unlogged gun buybacks (SOP 8.2), breaching a house without a signed warrant (SOP 9.2), and evidence mishandling.\n\n### 12.3 Inter-Agency Complaints\n\nComplaints involving FIB or other agencies are documented under SOP 21.3 and sent to LSPD High Command. IA investigates only the LSPD member's conduct.\n\n## 13. Discord Channels\n\n| Channel | Use |\n|---|---|\n| #internal-affairs-sops | These SOPs and division announcements. |\n| #ia-sealed-files | One thread per case using the pinned case file template. Nothing else is posted here. |\n| #strikes | Automatic strike posts from the strike2 tab. |\n").then(md=>{content.innerHTML=renderMarkdown(md);const sections=[...content.querySelectorAll(".sop-section")],buckets=new Map(groups.map(g=>[g.id,[]]));sections.forEach(s=>{const title=s.querySelector("h2").textContent,g=groups.find(x=>x.test(title))||groups[0];buckets.get(g.id).push(s)});tabs.innerHTML=groups.map(g=>'<button class="sop-tab" type="button" role="tab" id="tab-'+g.id+'" aria-controls="panel-'+g.id+'" aria-selected="false" data-tab="'+g.id+'">'+g.label+'<span>'+buckets.get(g.id).length+'</span></button>').join("");groups.forEach(g=>{const p=document.createElement("div");p.className="tab-panel";p.id="panel-"+g.id;p.setAttribute("role","tabpanel");p.setAttribute("aria-labelledby","tab-"+g.id);buckets.get(g.id).forEach(s=>p.appendChild(s));content.appendChild(p);panels.set(g.id,p)});sectionCount.textContent=sections.length+" handbook sections";tabs.addEventListener("click",e=>{const b=e.target.closest("[data-tab]");if(b)activate(b.dataset.tab)});searchInput.addEventListener("input",applySearch);activate(active)}).catch(e=>{content.innerHTML='<div class="loading-panel">The handbook could not be loaded. Check handbook.md.</div>';tabs.innerHTML='<div class="loading">Division tabs unavailable.</div>';console.error(e)});
function activate(id){active=id;groups.forEach(g=>{const b=tabs.querySelector('[data-tab="'+g.id+'"]'),p=panels.get(g.id),on=g.id===id;b.setAttribute("aria-selected",String(on));b.tabIndex=on?0:-1;p.hidden=!on});applySearch()}
function applySearch(){const q=searchInput.value.trim().toLowerCase();let shown=0,total=0;groups.forEach(g=>{const p=panels.get(g.id);if(!p)return;const ss=[...p.querySelectorAll(".sop-section")];let matches=0;ss.forEach(s=>{const ok=!q||s.textContent.toLowerCase().includes(q);s.classList.toggle("search-hidden",!ok);if(ok){matches++;total++}});const b=tabs.querySelector('[data-tab="'+g.id+'"]');b.querySelector("span").textContent=q?matches:ss.length;b.classList.toggle("tab-no-match",!!q&&!matches);if(g.id===active)shown=matches});noResults.hidden=shown!==0;searchStatus.textContent=q?"Showing "+shown+" matching sections in this tab; "+total+" matches across all tabs.":""}
document.getElementById("menuButton").addEventListener("click",()=>document.querySelector(".top-actions").classList.toggle("open"));